INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_hd_01', 'Resolving Windows Network Connectivity & DHCP Failures', 'عیب‌یابی مشکلات اتصال شبکه و عدم دریافت IP از DHCP در ویندوز', 'Step-by-step diagnostic workflow for IP lease renewal, socket resets, and DNS resolution.', 'مراحل گام‌به‌گام دریافت مجدد آی‌پی، ریست سوکت‌های شبکه و رفع خطاهای اتصال کلاینت.', 'When client computers display ''No Internet Access'' or 169.254.x.x (APIPA) addresses, follow this systematic procedure to isolate physical link issues, driver stack corruption, or DHCP exhaustion.', 'help-desk', 'Network Connectivity', 'Microsoft Windows', 'Fundamental', 'DHCP, IPConfig, Winsock, DNS, Network Adapter');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_hd_02', 'Troubleshooting Print Spooler Crashes and Network Printers', 'عیب‌یابی توقف سرویس پرینت اسپولر و پرینترهای تحت شبکه', 'Clearing corrupted print queues, restarting spooler services, and checking port 9100 Raw/LPR communication.', 'پاک‌سازی صف پرینت خراب، ریستارت سرویس Spooler و تست ارتباط پورت ۹۱۰۰ پرینتر.', 'Network printers frequently encounter hung jobs in the Windows print spooler queue (C:\\Windows\\System32\\spool\\PRINTERS). This guide provides automated PowerShell one-liners to clear stuck spool files safely.', 'help-desk', 'Printing', 'Windows / HP / Canon', 'Fundamental', 'Print Spooler, Port 9100, RAW, LPR');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_hd_03', 'Resolving Remote Desktop (RDP) Protocol Failures & Port 3389', 'رفع خطاهای اتصال ریموت دسکتاپ RDP و پورت ۳۳۸۹', 'Diagnosing NLA (Network Level Authentication) mismatches, Windows Firewall blocks, and registry port changes.', 'بررسی خطاهای NLA، فایروال ویندوز و تغییر پورت پیش‌فرض RDP.', 'Remote Desktop connection failures usually stem from: disabled Remote Desktop setting, Windows Firewall blocking port 3389, CredSSP encryption oracle remediation mismatch, or NLA requirements.', 'help-desk', 'Remote Support', 'Microsoft Windows', 'Intermediate', 'RDP, 3389, NLA, CredSSP, Firewall');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_net_01', 'OSI vs TCP/IP Models & Protocol Data Units (PDU)', 'مقایسه مدل‌های هفت‌لایه OSI و TCP/IP و واحدهای داده (PDU)', 'Deep dive into encapsulation, Layer 2 frames, Layer 3 packets, Layer 4 segments, and Layer 7 data.', 'بررسی کپسوله‌سازی دیتا، فریم لایه ۲، پکت لایه ۳ و سگمنت لایه ۴.', 'Understanding network protocol encapsulation is the cornerstone of all network engineering and packet analysis. Each layer prepends its header:\n\n1. Application (Data)\n2. Transport (Segment with TCP/UDP ports)\n3. Network (Packet with Source/Destination IP)\n4. Data Link (Frame with MAC addresses and FCS)\n5. Physical (Bits on copper/fiber/radio).', 'network-plus', 'Fundamentals', 'CompTIA / IEEE', 'Fundamental', 'OSI, TCP/IP, PDU, Encapsulation, MAC, IP');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_net_02', 'IPv4 Subnetting, CIDR Notation & VLSM Allocation', 'محاسبات ساب‌نتینگ IPv4، نماد CIDR و تخصیص VLSM', 'Mastering powers of two, subnet boundary math, host formula (2^h - 2), and prefix lengths.', 'فرمول تعداد هاست، تشخیص آدرس شبکه و برودکست و مرزهای ساب‌نت.', 'A subnet mask separates the 32-bit IPv4 address into Network Bits and Host Bits. Formula for usable hosts: 2^h - 2 (subtracting network and broadcast addresses). A /24 provides 254 hosts; /26 provides 62 hosts; /30 provides 2 hosts for point-to-point router links.', 'network-plus', 'Addressing', 'IETF', 'Intermediate', 'Subnetting, CIDR, VLSM, IPv4, Addressing');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_ccna_01', 'Cisco Switch VLAN Configuration & 802.1Q Trunking', 'پیکربندی VLAN و پورت‌های ترانک 802.1Q در سوئیچ سیسکو', 'Configuring access ports, creating VLANs, and establishing IEEE 802.1Q trunk links between switches.', 'تنظیم پورت‌های اکسس، تعریف وی‌لن و فعال‌سازی ترانک 802.1Q بین سوئیچ‌ها.', 'Virtual LANs (VLANs) segment broadcast domains on Layer 2 switches. Trunk links carry multiple VLANs across switches using 4-byte 802.1Q tags containing the 12-bit VLAN ID (1 to 4094).', 'ccna', 'Switching', 'Cisco Systems', 'Intermediate', 'VLAN, Trunk, 802.1Q, Cisco IOS, Switchport');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_ccna_02', 'Single-Area OSPFv2 Routing Configuration and Neighbors', 'پیکربندی پروتکل مسیریابی OSPFv2 تک‌ناحیه‌ای در سیسکو', 'Enabling Open Shortest Path First, router-ids, network statements, and adjacency verification.', 'راه‌اندازی OSPFv2، تنظیم Router ID، دستور network و بررسی وضعیت Neighbor.', 'OSPF is a link-state interior gateway routing protocol (IGP) using the Dijkstra SPF algorithm. Routers form neighbor adjacencies through Hello packets (multicast 224.0.0.5) and exchange Link State Advertisements (LSAs).', 'ccna', 'Routing', 'Cisco Systems', 'Intermediate', 'OSPF, Routing, Area 0, Dijkstra, Router-ID');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_ccnp_01', 'BGP (Border Gateway Protocol) eBGP and iBGP Peering', 'پیکربندی همسایگی BGP (eBGP و iBGP) و فیلترینگ مسیر', 'Autonomous System peering, next-hop-self, route-maps, and prefix-lists.', 'اتصال ASهای مختلف، دستور next-hop-self، روت‌مپ و پالیسی‌های BGP.', 'BGP is the path-vector protocol that powers the global Internet. eBGP operates between different Autonomous Systems (AS) with default TTL of 1, while iBGP operates within the same AS and requires a full mesh or Route Reflectors due to split-horizon rules.', 'ccnp', 'Advanced Routing', 'Cisco Systems', 'Advanced', 'BGP, eBGP, iBGP, AS, Route-Map, Prefix-List');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_mt_01', 'MikroTik RouterOS NAT Masquerade & Port Forwarding (Dst-NAT)', 'پیکربندی NAT سورس (Masquerade) و پورت فورواردینگ در میکروتیک', 'Configuring Internet NAT masquerading and exposing internal servers safely via dstnat.', 'اشتراک اینترنت با مسکورید و انتقال پورت به سرورهای داخلی با dstnat.', 'MikroTik RouterOS handles network address translation in `/ip firewall nat`. Masquerade rewrites source IP to outgoing WAN IP. Dst-NAT redirects incoming WAN traffic to internal servers (such as RDP or Web portals).', 'mikrotik', 'Firewall & NAT', 'MikroTik', 'Intermediate', 'MikroTik, RouterOS, NAT, Masquerade, Port Forward, Dst-NAT');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_mt_02', 'MikroTik RouterOS WireGuard Site-to-Site & Client VPN', 'راه‌اندازی تونل سریع و امن WireGuard در روتربورد میکروتیک', 'Creating modern lightweight WireGuard interfaces, peers, and static routes.', 'ساخت اینترفیس وایرگارد، تعریف Peerها و مسیریابی بین شعب.', 'WireGuard in RouterOS v7 provides high-speed encrypted UDP tunneling using modern cryptography (Curve25519, ChaCha20, Poly1305).', 'mikrotik', 'VPN', 'MikroTik', 'Intermediate', 'WireGuard, VPN, RouterOS v7, Cryptography');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_fg_01', 'FortiGate IPsec VPN Site-to-Site & CLI Debug Flow', 'تونل IPsec بین دیتاسنترها و عیب‌یابی با Debug Flow در فورتی‌گیت', 'IKE Phase 1, Phase 2, Firewall Policies, and live packet inspection via CLI.', 'تنظیم فاز ۱ و ۲، نوشتن پالیسی‌های فایروال و ردگیری زنده پکت‌ها با Debug Flow.', 'FortiGate firewalls require phase1-interface, phase2-interface, address objects, and bidirectional firewall policies. When packets drop, `diagnose debug flow` provides real-time state engine insights.', 'fortigate', 'IPsec & Debugging', 'Fortinet', 'Advanced', 'FortiGate, IPsec, VPN, Debug Flow, Packet Capture');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_win_01', 'Active Directory Domain Controller Health & Replication Check', 'بررسی سلامت دامین کنترلر، ریپلیکیشن و FSMO رول‌ها در اکتیو دایرکتوری', 'Running DCDiag, Repadmin, and FSMO queries across domain controllers.', 'اجرای دستورات dcdiag و repadmin برای اطمینان از سلامت اکتیو دایرکتوری و رفع خطاهای ریپلیکیشن.', 'In multi-DC environments (like Ardakan and Jahan), maintaining synchronized AD databases (NTDS.dit) is critical for Kerberos ticket issuance, user authentication, and group policy application.', 'windows-server', 'Active Directory', 'Microsoft Windows Server', 'Advanced', 'Active Directory, Domain Controller, Repadmin, DCDiag, FSMO');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_win_godmode', 'God Mode & Master Control Panel GUID', 'ترفند فعال‌سازی گاد مود (God Mode) و کنترل‌پنل جامع مخفی ویندوز', 'Unlocking the hidden master control panel containing over 200+ administrative applets in a single folder.', 'دسترسی به بیش از ۲۰۰ تنظیم و ابزار مدیریتی ویندوز در یک پوشه واحد بدون نیاز به گشتن در کنترل‌پنل.', 'Windows contains an undocumented GUID-based namespace junction that aggregates every Administrative Tool, Security setting, Device Manager, and Network Config into a searchable folder. Create a new folder anywhere and name it with the exact canonical GUID string.', 'windows-tricks', 'Productivity & Tweaks', 'Microsoft Windows', 'Fundamental', 'GodMode, GUID, Shell, Control Panel, Shortcut');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_win_tcptune', 'Turbocharge Windows Network Stack (TCP Window Auto-Tuning & Offloads)', 'بهینه‌سازی و افزایش سرعت پهنای باند شبکه ویندوز با تنظیمات پیشرفته TCP', 'Tuning Receive Window Auto-Tuning, RSS (Receive Side Scaling), and Chimney Offload for maximum gigabit throughput.', 'رفع افت سرعت دانلود و انتقال فایل در شبکه گیگابیت با فعال‌سازی TCP Auto-Tuning و تنظیمات netsh.', 'By default, Windows may restrict TCP receive windows on certain network adapters or legacy profiles, artificially bottlenecking high-speed 1Gbps/10Gbps transfers. Using netsh commands elevates the TCP stack to optimal performance.', 'windows-tricks', 'Network Tuning', 'Microsoft Windows', 'Intermediate', 'TCP, Netsh, Auto-Tuning, RSS, Bandwidth, Speed');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_win_fixupdate', 'Rescue Stuck Windows Update Engine & Reset SoftwareDistribution Store', 'حل مشکل هنگ و خطاهای آپدیت ویندوز با پاک‌سازی کامل پوشه SoftwareDistribution', 'Terminating update services, purging corrupted update caches, and re-registering BITS/WUAUSERV DLLs.', 'تعمیر خطاهای 0x80070002 و 0x80240034 هنگام نصب آپدیت با متوقف‌سازی سرویس‌ها و تخلیه کش دانلود.', 'Corrupted download chunks in C:\\Windows\\SoftwareDistribution frequently cause Windows Update to freeze at 0% or loop indefinitely. This proven sequence cleanly drains the queue.', 'windows-tricks', 'Maintenance', 'Microsoft Windows', 'Intermediate', 'Windows Update, SoftwareDistribution, BITS, WUAUSERV, Fix');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_win_winsxs', 'Reclaim 20GB+ Disk Space: Deep Clean WinSxS Component Store via DISM', 'آزادسازی فضای درایو C با پاک‌سازی عمیق انبار مؤلفه‌های WinSxS از طریق DISM', 'Safely purging superseded Windows updates, obsolete service packs, and backup packages.', 'حذف فایل‌های آپدیت قدیمی و جایگزین‌شده در پوشه حجیم WinSxS بدون صدمه به سیستم‌عامل.', 'The WinSxS (Windows Side-by-Side) folder accumulates superseded version binaries after every monthly cumulative patch. Standard Disk Cleanup misses these, but DISM commands with /ResetBase permanently prune superseded revisions.', 'windows-tricks', 'Disk Optimization', 'Microsoft Windows', 'Intermediate', 'DISM, WinSxS, Disk Cleanup, Storage, ResetBase');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_win_taskkill', 'Force Kill Frozen Processes Holding Open Ports & File Locks', 'بستن اجباری پروسه‌های هنگ کرده و آزادکردن فوری پورت‌های اشغال‌شده', 'Finding the exact PID holding a network port (like 80, 443, 3389, 7300) and terminating its process tree immediately.', 'تشخیص شناسه پروسه (PID) مسدودکننده پورت با netstat و بستن اجباری درخت پروسه با taskkill /f /t.', 'When an application fails to start because ''Port is already in use'', standard Task Manager might hide the child process. Use netstat to map port to PID, then taskkill /f /t to obliterate it.', 'windows-tricks', 'Troubleshooting', 'Microsoft Windows', 'Fundamental', 'Taskkill, Netstat, PID, Ports, Freeze, Kill');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_win_powerplan', 'Unlock Hidden ''Ultimate Performance'' Power Plan in Windows', 'فعال‌سازی پلن مصرف انرژی مخفی Ultimate Performance برای حداکثر بازدهی', 'Unlocking the workstation-grade power plan that eliminates micro-latencies and CPU core parking.', 'حذف تاخیرهای فرکانسی و جلوگیری از به خواب رفتن هسته‌های پردازنده در سرورها و سیستم‌های تحت فشار.', 'Microsoft developed the ''Ultimate Performance'' power scheme for high-end workstations and servers. It bypasses conventional power-saving heuristics to maximize real-time hardware response.', 'windows-tricks', 'Performance', 'Microsoft Windows', 'Fundamental', 'Powercfg, Ultimate Performance, CPU, Speed, Latency');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_win_winget', 'Automated Fleet Software Deployment & Bulk Updates via WinGet', 'نصب و بروزرسانی خودکار و سایلنت نرم‌افزارهای سازمانی با اسکریپت WinGet', 'Installing Google Chrome, 7-Zip, AnyDesk, Notepad++, Putty, Wireshark silently with a single PowerShell line.', 'راه‌اندازی فوری کلاینت جدید بدون نیاز به دانلود دستی نرم‌افزارها و کلیک بر روی گزینه‌های Next.', 'Windows Package Manager (winget) allows IT administrators to deploy official vendor packages silently in seconds, bypassing bundled adware and manual installer clicks.', 'windows-tricks', 'Automation', 'Microsoft Windows', 'Intermediate', 'WinGet, Automation, Deployment, Silent Install, Fleet');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_hd_bsod', 'Blue Screen of Death (BSOD) Minidump Triage & Crash Dump Analysis', 'عیب‌یابی تخصصی صفحه آبی مرگ (BSOD) و تحلیل فایل‌های دامپ با WinDbg', 'Locating memory dumps, reading bugcheck codes (CRITICAL_PROCESS_DIED, KERNEL_SECURITY_CHECK), and isolating faulty driver sys files.', 'بررسی خطاهای Stop Code و مشخص‌کردن درایور یا سخت‌افزار مقصر از روی فایل‌های Minidump.', 'When Windows crashes with a BSOD, a crash dump is recorded in C:\\Windows\\Minidump. Using PowerShell and dump utilities pinpoints the exact driver filename (e.g., nvlddmkm.sys, netwtw08.sys) causing the kernel panic.', 'help-desk', 'Crash Analysis', 'Microsoft Windows', 'Advanced', 'BSOD, Minidump, WinDbg, Bugcheck, Driver, Crash');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_hd_profile', 'Fixing Temporary Profile Logins & Corrupted Windows User Profiles', 'حل مشکل ورود کاربر با پروفایل موقت (We can''t sign in to your account) در رجیستری', 'Fixing the ProfileList registry key .bak extension to restore access to Desktop and Documents.', 'حذف پسوند .bak در شاخه ProfileList رجیستری و بازگردانی پروفایل اصلی کاربر بدون از دست رفتن فایل‌ها.', 'If a user signs in and sees ''You''ve been signed in with a temporary profile'', Windows failed to lock NTUSER.DAT. The solution involves renaming the .bak registry key in HKLM\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\ProfileList.', 'help-desk', 'User Accounts', 'Microsoft Windows', 'Intermediate', 'Profile, Temp Profile, Registry, ProfileList, SID, Fix');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_ccna_roas', 'Cisco Router-on-a-Stick Inter-VLAN Routing with 802.1Q Subinterfaces', 'مسیریابی بین وی‌لن‌ها با متد Router-on-a-Stick در روتر و سوئیچ سیسکو', 'Configuring physical router subinterfaces (e.g. g0/0.10, g0/0.20) with 802.1Q encapsulation for inter-VLAN forwarding.', 'اتصال یک پورت ترانک به روتر و تعریف ساب‌اینترفیس‌ها به همراه آی‌پی‌های گیت‌وی هر VLAN.', 'Router-on-a-Stick (ROAS) routes traffic between different VLANs using a single physical interface connected via an 802.1Q trunk link to a Layer 2 switch.', 'ccna', 'Routing', 'Cisco Systems', 'Intermediate', 'ROAS, Inter-VLAN, Subinterface, 802.1Q, Cisco');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_ccnp_redist', 'OSPF and BGP Mutual Route Redistribution with Route-Maps', 'بازتوزیع دوطرفه مسیرها (Redistribution) بین OSPF و BGP با Route-Map', 'Safely redistributing prefixes, preventing routing loops with tags, and setting metric types.', 'انتقال روت‌ها بین شبکه‌های OSPF داخلی و BGP خارجی با جلوگیری از ایجاد لوپ روتینگ با تگ‌گذاری.', 'Redistribution introduces routing loops unless strict route filtering and tagging are enforced. Tagging incoming routes allows mutual redistribution without route re-injection.', 'ccnp', 'Advanced Routing', 'Cisco Systems', 'Advanced', 'Redistribution, OSPF, BGP, Route-Map, Metric, Tags');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_mt_pcc', 'MikroTik PCC Dual-WAN Load Balancing with Failover', 'لودبالانس و ترکیب پهنای باند دو خط اینترنت (PCC) در میکروتیک به همراه Failover', 'Configuring Per Connection Classifier (PCC) in firewall mangle for seamless dual-ISP bandwidth distribution.', 'تقسیم هوشمند ترافیک کاربران بین دو اینترنت مختلف بر اساس سورس و مقصد با بازگشت خودکار در صورت قطعی.', 'Per Connection Classifier (PCC) groups connections based on hashing source/destination IP addresses, ensuring HTTPS sessions remain on the same WAN while utilizing full bandwidth of both links.', 'mikrotik', 'Bandwidth & Routing', 'MikroTik', 'Advanced', 'PCC, Load Balance, Dual-WAN, Mangle, Failover, MikroTik');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_fg_sdwan', 'FortiGate SD-WAN SLA Performance Probes & Automated Path Steering', 'تنظیم SD-WAN هوشمند و تغییر خودکار لینک اینترنت بر اساس کیفیت پکت در فورتی‌گیت', 'Configuring Performance SLAs (Packet Loss, Latency, Jitter) and SD-WAN rules for priority traffic.', 'ارزیابی دائم کیفیت خطوط اینترنت و هدایت ترافیک VoIP و دیتاسنتر به بهترین لینک با کمترین پکت‌لاس.', 'FortiGate SD-WAN tests link health using continuous DNS/Ping probes against cloud targets (8.8.8.8, 1.1.1.1). When latency or loss exceeds defined thresholds, traffic dynamically steers to alternate WAN members without dropping active TCP connections.', 'fortigate', 'SD-WAN', 'Fortinet', 'Advanced', 'SD-WAN, SLA, Jitter, Packet Loss, Failover, FortiGate');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_win_sfc_dism', 'Repair Corrupted Windows System Files & Component Store (SFC + DISM)', 'تعمیر کامل فایل‌های سیستمی و کرنل آسیب‌دیده با ترکیب SFC و DISM آنلاین', 'Dual-stage repair workflow utilizing DISM online image repair followed by SFC protected system file replacement.', 'رفع ارورهای سیستمی، کرش برنامه‌ها و فایل‌های dll دست‌کاری شده با بازگردانی سورس سالم از سرور مایکروسافت.', 'Running sfc /scannow alone often fails when the local component store (WinSxS) is itself corrupted. The enterprise gold standard is to repair the component store first with DISM /RestoreHealth, then let SFC regenerate system binaries.', 'windows-tricks', 'System Integrity', 'Microsoft Windows', 'Fundamental', 'SFC, DISM, RestoreHealth, Corruption, System32, DLL');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_win_mtu', 'Optimize Network MTU & Subinterface Packet Sizes (Zero Fragmentation)', 'بهینه‌سازی MTU کارت شبکه و رفع پکت‌لاس ناشی از قطعه‌قطعه شدن (Fragmentation)', 'Measuring the exact Maximum Transmission Unit with ping sweep and setting persistent subinterface MTU values.', 'حل مشکل لود نشدن برخی وب‌سایت‌ها و کندی شدید تونل‌های VPN با تنظیم دقیق مقدار MTU کارت شبکه.', 'When network packets exceed the Path MTU (especially over PPPoE or IPsec tunnels with encryption headers), packets fragment or drop silently. Tuning the Windows interface MTU guarantees 100% wire-speed transmission.', 'windows-tricks', 'Network Tuning', 'Microsoft Windows', 'Intermediate', 'MTU, Ping, Fragmentation, Netsh, Subinterface, VPN');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_win_robocopy', 'High-Speed Enterprise Multi-Threaded File Replication with Robocopy', 'انتقال فوق‌سریع اطلاعات و بکاپ‌گیری مولتی‌ترد با کامند پیشرفته Robocopy', 'Mirroring terabytes of enterprise file shares with ACL permissions, NTFS timestamps, and 16 concurrent worker threads.', 'کپی فایل‌های حجیم و اشتراک‌های سازمانی بدون افت سرعت و با حفظ کامل سطوح دسترسی امنیتی (NTFS Permissions).', 'Standard Windows Explorer file copy is single-threaded and locks on long filenames or open locks. Robocopy (Robust File Copy) with /MT:16 and /MIR replicates files at maximum hardware I/O saturation.', 'windows-tricks', 'Storage & Backup', 'Microsoft Windows', 'Intermediate', 'Robocopy, Multi-Thread, Mirror, NTFS, ACL, Backup');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_win_battery', 'Generate Deep Battery Diagnostics & PowerCfg Health Telemetry', 'تولید گزارش جامع سلامت باتری، ظرفیت و چرخه‌های شارژ لپ‌تاپ‌های سازمانی', 'Exporting interactive HTML telemetry detailing factory design capacity vs current full charge capacity.', 'تشخیص فرسودگی باتری، بررسی سیکل‌های شارژ و یافتن نرم‌افزارهای عامل تخلیه باتری در کمتر از چند ثانیه.', 'Enterprise laptops often suffer battery degradation that is invisible in standard battery meters. Windows contains a built-in diagnostic engine that creates a micro-auditing report of battery chemistry.', 'windows-tricks', 'Hardware Telemetry', 'Microsoft Windows', 'Fundamental', 'Battery, Powercfg, Capacity, Laptop, Health, Energy');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_win_symlinks', 'Create Directory Junctions & NTFS Symbolic Links (mklink)', 'هدایت فضا و انتقال پوشه‌های سنگین به درایو دیگر با دایرکتوری جانکشن (mklink /J)', 'Redirecting space-heavy application directories (AppData, iTunes, Docker, VMs) to secondary drives without breaking software paths.', 'آزادکردن ده‌ها گیگابایت از درایو C با انتقال پوشه‌ها به درایو D و ایجاد لینک سخت شفاف برای نرم‌افزارها.', 'NTFS Directory Junctions allow creating a transparent pointer at the filesystem driver level. Programs continue reading from C:\\... while the actual bytes reside on D:\\, completely invisible to the operating software.', 'windows-tricks', 'Storage Optimization', 'Microsoft Windows', 'Intermediate', 'mklink, Junction, Symlink, NTFS, AppData, Storage');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_win_sandbox', 'Windows Sandbox: Instant Disposable VM for Safe Malware & Script Triage', 'راه‌اندازی سندباکس ویندوز برای تست امن فایل‌های مشکوک، بدافزار و اسکریپت‌ها', 'Enabling hardware-isolated disposable lightweight Windows desktop that discards all state upon closure.', 'محیط مجازی موقت و ایزوله که با بستن پنجره آن، تمام فایل‌ها، تغییرات و بدافزارها برای همیشه پاک می‌شوند.', 'Windows Sandbox provides a pristine, isolated Hyper-V container utilizing the host kernel with zero persistent disk storage. Perfect for testing suspicious email attachments, untrusted software, or PowerShell scripts safely.', 'windows-tricks', 'Security & Isolation', 'Microsoft Windows', 'Fundamental', 'Sandbox, Isolation, Security, Malware, Disposable, Hyper-V');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_win_dnsflush', 'Purge DNS Resolver & NetBIOS Name Cache (Instant Domain Refresh)', 'تخلیه کامل کش دی‌ان‌اس و نت‌بایوس جهت مشاهده تغییرات فوری رکوردهای سرور', 'Clearing local resolver sockets, flushing cached NXDOMAIN responses, and re-registering Active Directory DNS names.', 'رفع ارور خطای باز شدن سایت یا سرور بعد از تغییر IP رکورد با تخلیه کش DNS کلاینت.', 'Windows caches negative (NXDOMAIN) and outdated DNS records locally. When a server IP changes, the client continues connecting to old IPs until the TTL expires unless cleared with this pipeline.', 'windows-tricks', 'Name Resolution', 'Microsoft Windows', 'Fundamental', 'DNS, FlushDNS, NetBIOS, Nbtstat, RegisterDNS, IPConfig');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_win_securechannel', 'Repair Broken Active Directory Domain Trust (Secure Channel Reset)', 'تعمیر قطعی ارتباط اعتماد کلاینت با دامین کنترلر (Trust Relationship Failure)', 'Repairing ''The trust relationship between this workstation and the primary domain failed'' without unjoining domain.', 'رفع خطای عدم پذیرش پسورد دامین و قطعی ارتباط با اکتیو دایرکتوری بدون نیاز به خروج و ورود مجدد به دامین.', 'When a workstation password machine account becomes out-of-sync with Active Directory Domain Controllers, users cannot sign in. Using PowerShell Reset-ComputerMachinePassword or Test-ComputerSecureChannel repairs the channel in place.', 'windows-tricks', 'Active Directory', 'Microsoft Windows', 'Intermediate', 'Domain, Trust, Secure Channel, Active Directory, PowerShell');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_hd_outlook_ost', 'Repair Corrupted Outlook Mail Profiles & Rebuild OST Data Files', 'حل خطای خرابی دیتابیس Outlook و ساخت مجدد فایل داده آفلاین OST', 'Resolving ''Cannot start Microsoft Outlook'', hung profile loading, and synchronizing fresh Exchange/IMAP mailbox cache.', 'رفع فریز شدن اوت‌لوک هنگام باز شدن با حذف فایل خراب OST و دانلود مجدد دیتابیس ایمیل از سرور.', 'Exchange and IMAP store cached mailbox items in %LOCALAPPDATA%\\Microsoft\\Outlook\\<email>.ost. Hard reboots or large mailboxes corrupt this file. Safely renaming the .ost forces Outlook to recreate a pristine database without data loss.', 'help-desk', 'Email & Messaging', 'Microsoft Outlook', 'Fundamental', 'Outlook, OST, Mail Profile, Exchange, Corrupt, Fix');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_hd_time_skew', 'Fix Active Directory Kerberos Time Skew & Time Sync Failure', 'حل خطای ساعت کلاینت با سرور و عدم پذیرش تیکت Kerberos در شبکه دامین', 'Resynchronizing workstation clocks with the PDC Emulator to resolve the 5-minute Kerberos ticket validity window.', 'تنظیم ساعت سیستم با سرور دامین برای رفع خطای Time Skew که مانع ورود کاربران و لاگین به شیرینگ‌ها می‌شود.', 'Kerberos protocol strictly limits clock drift to 5 minutes (default). If a client CMOS battery dies or time drifts, all domain logins and shared folder access fail with authentication errors.', 'help-desk', 'Domain Services', 'Microsoft Windows', 'Fundamental', 'NTP, Time Skew, Kerberos, W32tm, Domain Controller, Clock');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_hd_bitlocker', 'BitLocker Drive Encryption Recovery Key Retrieval & TPM Verification', 'استخراج کلید ریکاوری ۴۸ رقمی بیت‌لاکر و تست سلامت ماژول TPM مادربورد', 'Querying numerical password protectors, testing TPM hardware availability, and backing up keys to Active Directory.', 'دریافت کلید ریکاوری درایو C جهت باز کردن سیستم قفل‌شده و جلوگیری از فرمت شدن اطلاعات مهم کاربر.', 'When BIOS updates or secure boot changes trigger the BitLocker Recovery screen, IT support must supply the 48-digit numerical password. Using manage-bde commands extracts keys before system changes.', 'help-desk', 'Security & Encryption', 'Microsoft Windows', 'Intermediate', 'BitLocker, Recovery Key, TPM, Encryption, manage-bde');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_hd_proxy_reset', 'Reset WinHTTP Proxy & System Proxy PAC Autodiscovery', 'ریست پروکسی سیستم و رفع خطای قطعی اینترنت در اثر برنامه‌های فیلترشکن', 'Eliminating leftover proxy bindings in system sockets and resetting WinINet / WinHTTP to direct access.', 'رفع خطای ''Proxy server is not responding'' بعد از قطع شدن ناگهانی فیلترشکن‌ها و نرم‌افزارهای واسط.', 'VPN and proxy clients frequently leave 127.0.0.1:8080 proxy configurations in registry and WinHTTP settings after crashes. Standard browser resets do not clear system-level WinHTTP sockets.', 'help-desk', 'Internet Connectivity', 'Microsoft Windows', 'Fundamental', 'Proxy, WinHTTP, PAC, 127.0.0.1, Reset, Network');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_train_wireguard', 'MikroTik WireGuard High-Performance Site-to-Site VPN Tunnel', 'راه‌اندازی تونل پرسرعت وایرگارد (WireGuard) بین دو شعبه در میکروتیک RouterOS v7', 'Configuring UDP-based modern WireGuard crypto interfaces, public/private keys, peers, and static routes.', 'اتصال پایدار و با کمترین تاخیر بین دفاتر و کارخانه‌ها با پروتکل مدرن وایرگارد در RouterOS v7.', 'WireGuard replaces resource-heavy IPsec and OpenVPN with state-of-the-art cryptography (ChaCha20, Curve25519) in the Linux kernel space. It delivers up to 4x higher throughput on budget MikroTik hardware.', 'mikrotik', 'VPN & Tunnels', 'MikroTik', 'Advanced', 'WireGuard, VPN, MikroTik, RouterOS v7, Cryptography, Tunnel');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_train_forti_ipsec', 'FortiGate Site-to-Site IPsec VPN with IKEv2 & Dead Peer Detection (DPD)', 'پیکربندی تونل امن IPsec VPN بین فایروال فورتی‌گیت و شعبه با IKEv2 و DPD', 'Phase 1 / Phase 2 crypto proposals, interface binding, firewall policies, and static routing over VPN.', 'اتصال امن دیتاسنتر و شعب با رمزنگاری AES-256 و فعال‌سازی مکانیزم تشخیص سریع قطعی لینک (DPD).', 'IPsec VPN tunnels establish end-to-end encrypted transport across the public internet. Utilizing IKEv2 accelerates rekeying and handles asymmetric routing effectively.', 'fortigate', 'IPsec VPN', 'Fortinet', 'Advanced', 'IPsec, IKEv2, FortiGate, VPN, Phase 1, Phase 2, Firewall');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_train_cisco_ospf', 'Cisco OSPF Multi-Area Design & Dead Interval Optimization', 'طراحی OSPF چندمنطقه‌ای (Multi-Area) و تنظیم تایمرهای Dead برای همگرایی سریع', 'Configuring Area Border Routers (ABRs), Area 0 backbone, route summarization, and sub-second convergence.', 'تقسیم شبکه به چند Area در OSPF برای کاهش لود پردازشی روترها و کاهش زمان Down شدن به زیر ۲ ثانیه.', 'In large campus networks, running all routers in a single OSPF Area 0 leads to excessive SPF recalculations on link flaps. Designing hierarchical areas with ABRs isolates flooding domains.', 'ccna', 'Dynamic Routing', 'Cisco Systems', 'Intermediate', 'OSPF, Area 0, ABR, Convergence, Dead Interval, Cisco');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_train_vmware_vmotion', 'VMware vSphere ESXi vMotion & Distributed Switch VLAN Portgroups', 'پیکربندی vMotion و پورت‌گروه‌های سوئیچ توزیع‌شده (vDS) برای مهاجرت زنده ماشین‌های مجازی', 'Configuring VMkernel interfaces with vMotion TCP/IP stacks, 802.1Q VLAN trunking, and zero-downtime VM migration.', 'مهاجرت زنده سرورهای ERP بدون حتی یک پکت قطعی با راه‌اندازی شبکه مجزای vMotion در کلاستر vCenter.', 'Live migration (vMotion) transfers active VM memory state over the network while the virtual CPU continues executing. Setting up dedicated VMkernel adapters on 10Gbps uplinks with jumbo frames prevents migration timeouts.', 'windows-server', 'Virtualization', 'VMware Broadcom', 'Advanced', 'vSphere, ESXi, vMotion, vCenter, VLAN, Distributed Switch');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_train_windows_ad', 'Windows Server 2022/2025 AD DS Disaster Recovery & FSMO Role Transfer', 'بازیابی بحران اکتیو دایرکتوری و انتقال فوری رول‌های FSMO با کامند ntdsutil', 'Seizing Flexible Single Master Operation (FSMO) roles when the Primary Domain Controller crashes permanently.', 'مدیریت بحران سوختن سرور دامین کنترلر اصلی و ارتقای سرور بکاپ به عنوان سرور جامع دامین بدون از دست رفتن کاربران.', 'Active Directory relies on 5 FSMO roles: Schema Master, Domain Naming Master, PDC Emulator, RID Master, and Infrastructure Master. If the PDC dies, seizing roles via ntdsutil restores domain functionality.', 'windows-server', 'Active Directory Disaster Recovery', 'Microsoft Windows Server', 'Advanced', 'FSMO, ntdsutil, AD DS, Disaster Recovery, Active Directory, PDC');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_win_portproxy', 'Native Windows Port Forwarding & NAT with netsh interface portproxy', 'هدایت پورت و فورواردینگ ترافیک در ویندوز بدون نرم‌افزار اضافی با netsh portproxy', 'Redirecting incoming traffic on any port to another internal IP or WSL container transparently.', 'انتقال ترافیک پورت‌های ورودی به آی‌پی یا پورت دیگر در شبکه محلی یا کانتینرهای لینوکسی در سطح ویندوز.', 'Windows includes a native Layer-4 TCP portproxy within the netsh networking subsystem. It allows administrators to route incoming requests on port 8080 to an internal database or web server on 192.168.1.50:80 without installing third-party proxies.', 'windows-tricks', 'Network Redirection', 'Microsoft Windows', 'Intermediate', 'Netsh, Portproxy, Port Forwarding, NAT, TCP, Firewall');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_win_godmode', 'Activate Windows God Mode & All-in-One Master Administrative Panel', 'فعال‌سازی پنل مدیریت کل (God Mode) و دسترسی به تمام ابزارهای ادمین ویندوز در یک پوشه', 'Creating a unified management console with all 200+ Control Panel tools, MMC snap-ins, and security settings.', 'ایجاد پوشه جادویی God Mode با دسترسی آنی به بیش از ۲۰۰ ابزار عیب‌یابی، مدیریت سرویس‌ها و تنظیمات مخفی ویندوز.', 'Windows contains a hidden master GUID namespace {ED7BA470-8E54-465E-825C-99712043E01C} that compiles all configuration applets, device manager tools, security policies, and power settings into a single searchable interface.', 'windows-tricks', 'Administration', 'Microsoft Windows', 'Fundamental', 'God Mode, Master Control, Admin Tools, Shortcuts, System Administration');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_win_psremoting', 'Multi-Host Remote Management via WinRM & PowerShell Remoting', 'مدیریت ریموت و همزمان کلاینت‌های تحت شبکه با WinRM و دستورات Invoke-Command', 'Executing commands, querying hardware, and pushing software configurations across 50 computers concurrently.', 'اجرای همزمان اسکریپت روی صدها کامپیوتر تحت شبکه دامین یا ورک‌گروپ در کمتر از چند ثانیه از طریق پروتکل WinRM.', 'PowerShell Remoting uses Windows Remote Management (WinRM) over WS-Management protocol (ports 5985/5986). It allows system administrators to manage remote computers headless without opening GUI Remote Desktop.', 'windows-tricks', 'Remote Management', 'Microsoft Windows', 'Intermediate', 'PowerShell, WinRM, Enter-PSSession, Invoke-Command, Remote Administration');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_net_subnet_mastery', 'IPv4 Subnetting Math, Magic Number & High-Speed Network Planning', 'راهنمای جامع محاسبات ذهنی ساب‌نتینگ، فرمول عدد جادویی و طراحی رنج آی‌پی', 'Mastering subnet mask calculations, broadcast boundaries, usable host formulas, and CIDR prefix math.', 'آموزش گام‌به‌گام و فرمول‌های سریع محاسبه آی‌پی شبکه، برودکست، هاست‌های قابل استفاده و طراحی ساب‌نت در سناریوهای واقعی.', 'Subnetting allows dividing a contiguous IP address block into smaller network segments for security, performance, and broadcast domain isolation. The Magic Number method (256 minus the interesting octet value) provides the interval step for every subnet block.', 'ccna', 'IP Addressing & Subnetting', 'Cisco / IETF', 'Fundamental', 'Subnetting, CIDR, Magic Number, IPv4, Broadcast, Network ID, VLSM');
INSERT OR REPLACE INTO academy_articles (id, title, title_fa, summary, summary_fa, content, category_slug, subcategory, vendor, difficulty, tags) VALUES ('art_net_vlsm_design', 'Variable Length Subnet Masking (VLSM) Architectural Hierarchy', 'طراحی معماری آدرس‌دهی سلسله‌مراتبی با ماسک با طول متغیر (VLSM)', 'Optimizing IPv4 allocations for disparate department sizes without wasting address space.', 'تخصیص هوشمندانه بلاک‌های ساب‌نت از بزرگ‌ترین نیاز تا کوچک‌ترین لینک‌های نظیربه‌نظیر Point-to-Point (/30 و /31).', 'Variable Length Subnet Masking (VLSM) allows multiple subnet masks to exist within the same classful address space. The golden rule of VLSM design is to always order requirement sizes from largest to smallest, avoiding overlapping addresses.', 'ccna', 'Subnet Engineering', 'Cisco CCNA', 'Intermediate', 'VLSM, Subnetting, IPv4, Optimization, Point-to-Point, CIDR');